                            st23 = 4
                        }
                        3u -> {   // SE(DigestMethod)
                            _digestMethod = decodeDigestMethodType(r)
                            done23 = true
                        }
                        else -> throw IllegalArgumentException("invalid optional-run event code")
                    }
                }
                2 -> {
                    when (r.readBits(2)) {
                        0u -> {
                            _uRI = ExiPrimitives.readStringValue(r)
                            st23 = 3
                        }
                        1u -> {
                            _transforms = decodeTransformsType(r)
                            st23 = 4
                        }
                        2u -> {   // SE(DigestMethod)
                            _digestMethod = decodeDigestMethodType(r)
                            done23 = true
