    private fun encodeTransformsType(w: BitWriter, msg: TransformsType) {
        val list = msg.transform
        require(list.size in 1..2147483647) { "list size out of schema range" }
        for (i in list.indices) {
            w.writeBits(0u, if (i == 0) 1 else 2)   // SE(item)
            encodeTransformType(w, list[i])
        }
        w.writeBits(1u, 2)   // list terminator / element EE
    }

    private fun decodeTransformsType(r: BitReader): TransformsType {
        val list = ArrayList<TransformType>()
        r.readBits(1)   // SE(item) first
        list.add(decodeTransformType(r))
        while (true) {
            val ec = r.readBits(2)
            if (ec == 1u) break   // element EE
            require(ec == 0u && list.size < 2147483647) { "invalid repeating-element event code" }
            list.add(decodeTransformType(r))
        }
        return TransformsType(list)
    }

    private fun encodeTransformType(w: BitWriter, msg: TransformType) {
